// n8n Code node: validate the public form and minimize stored request metadata.
const input = $input.first().json;
const body = input.body && typeof input.body === 'object' ? input.body : {};
const text = (key, max = 200) => typeof body[key] === 'string' ? body[key].trim().slice(0, max) : '';
const services = ['Tree Trimming', 'Tree Removal', 'Stump Removal', 'Palm Tree Service', 'HOA / Commercial', 'Emergency — call me ASAP'];
const name = text('name', 100), phone = text('phone', 40), service = text('service', 80);
const email = text('email', 254), postal_code = text('postal_code', 10);
// Version 2 requires a complete service address. Older deployed forms remain
// accepted during rollout; never turn their ZIP alone into a property map.
const form_version = text('form_version', 10);
const street_address = text('street_address', 161), address_line2 = text('address_line2', 81);
const city = text('city', 101), state = text('state', 3).toUpperCase();
const addressRequired = form_version === '2' || Boolean(street_address || address_line2 || city || state);
const requestedId = text('lead_id', 80), modern = Boolean(requestedId);
const errors = [];
const tree_count = text('tree_count', 40);
const requestedHeight = text('tree_height', 40);
const tree_height = service === 'Stump Removal' ? '' : requestedHeight;
const discount_code = text('discount_code', 33).toUpperCase();
if (!['', 'Not sure', '1', '2–3', '4–6', '7+'].includes(tree_count)) errors.push('tree_count');
if (!['', 'Not sure', 'Under 15 ft', '15–30 ft', '30–50 ft', 'Over 50 ft'].includes(tree_height)) errors.push('tree_height');
if (discount_code && !/^[A-Z0-9_-]{1,32}$/.test(discount_code)) errors.push('discount_code');
if (text('website', 500)) errors.push('invalid_request');
if (name.length < 2 || /[\r\n]/.test(name)) errors.push('name');
const digits = phone.replace(/\D/g, '');
if (!/^\+?[\d\s().-]+$/.test(phone) || digits.length < 10 || digits.length > 15 || /^(\d)\1+$/.test(digits)) errors.push('phone');
if (!services.includes(service)) errors.push('service');
if ((modern || postal_code) && !/^\d{5}(?:-\d{4})?$/.test(postal_code)) errors.push('postal_code');
if (form_version && form_version !== '2') errors.push('form_version');
if (addressRequired) {
  if (street_address.length < 5 || street_address.length > 160 || /[\u0000-\u001f\u007f]/.test(street_address)) errors.push('street_address');
  if (address_line2.length > 80 || /[\u0000-\u001f\u007f]/.test(address_line2)) errors.push('address_line2');
  if (city.length < 2 || city.length > 100 || /[\u0000-\u001f\u007f]/.test(city)) errors.push('city');
  if (state !== 'CA') errors.push('state');
  if (!/^\d{5}(?:-\d{4})?$/.test(postal_code) && !errors.includes('postal_code')) errors.push('postal_code');
}
if (email && !/^[^\s@<>]+@[^\s@<>]+\.[^\s@<>]+$/.test(email)) errors.push('email');
if (modern && !/^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/i.test(requestedId)) errors.push('lead_id');
const timeline = text('timeline', 80) || 'Flexible';
if (!['Flexible', 'As soon as possible', 'This week', 'Within a month'].includes(timeline)) errors.push('timeline');
const contact_preference = text('contact_preference', 10) || 'Call';
if (!['Call', 'Text'].includes(contact_preference)) errors.push('contact_preference');
// URL query strings can contain unrelated personal information. Never retain them.
function safeUrl(value) {
  const match = value.match(/^(https?:\/\/[^/?#\s]+)([^?#\s]*)/i);
  return match && !match[1].includes('@') ? (match[1] + match[2]).slice(0, 1000) : '';
}
const lead = {
  name, phone, service, email, postal_code, timeline, contact_preference,
  form_version, street_address, address_line2, city, state, tree_count, tree_height, discount_code,
  property_address: street_address && city && state && postal_code
    ? [street_address, address_line2, city + ', ' + state + ' ' + postal_code].filter(Boolean).join(', ') : '',
  details: text('details', 3000),
  language: text('language', 5) === 'es' ? 'es' : 'en',
  lead_id: modern ? requestedId.toLowerCase() : 'legacy-' + $execution.id,
  receivedAt: new Date().toISOString(), source: 'website',
  page_url: safeUrl(text('page_url', 1200)), referrer: safeUrl(text('referrer', 1200)),
  browser_language: text('browser_language', 40), timezone: text('timezone', 100),
  viewport: text('viewport', 30), submitted_at: text('submitted_at', 40),
  status: 'New', email_status: 'pending', email_sent_at: '', gmail_message_id: '', email_error: ''
};
for (const key of ['utm_source', 'utm_medium', 'utm_campaign', 'utm_content', 'utm_term']) lead[key] = text(key, 200);
// Preserve only the accepted form fields, never cookies, authorization headers or IP addresses.
lead.raw_payload = JSON.stringify(Object.fromEntries(Object.keys(lead).filter(k => !['status','email_status','email_sent_at','gmail_message_id','email_error','receivedAt'].includes(k)).map(k => [k, lead[k]])));
return [{json: { ...lead, valid: errors.length === 0, errors }}];

// LC Marketing: yellow, black and white confirmed by owner. Yellow #FECE00 sampled from supplied logo; see brand/README.txt.
const lead = $('Validate Lead').first().json;
const esc = value => String(value || 'Not provided').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const row = (label, value) => '<tr><th style="text-align:left;vertical-align:top;padding:10px 12px;border-bottom:1px solid #dedede;width:32%;color:#444444;font-size:14px">' + esc(label) + '</th><td style="padding:10px 12px;border-bottom:1px solid #dedede;word-break:break-word;font-size:15px">' + esc(value).replace(/\n/g, '<br>') + '</td></tr>';
const table = rows => '<table role="presentation" style="border-collapse:collapse;width:100%;margin:12px 0 24px">' + rows.join('') + '</table>';
const emergency = lead.service.startsWith('Emergency');
const heading = emergency ? 'Urgent tree service request' : 'New tree service estimate';
const language = lead.language === 'es' ? 'Spanish / Español' : 'English';
const received = new Date(lead.receivedAt).toLocaleString('en-US', {timeZone:'America/Los_Angeles',dateStyle:'medium',timeStyle:'short'}) + ' Pacific';
const phoneDigits = lead.phone.replace(/\D/g, '');
// Use international format for US numbers; retain explicit international input.
const phoneHref = lead.phone.trim().startsWith('+') ? '+' + phoneDigits
  : phoneDigits.length === 10 ? '+1' + phoneDigits
  : phoneDigits.length === 11 && phoneDigits.startsWith('1') ? '+' + phoneDigits : phoneDigits;
const discount = lead.discount_code === 'WEB10'
  ? 'WEB10 — 10% discount requested. Confirm eligibility with the estimate.'
  : lead.discount_code ? lead.discount_code + ' — customer-entered code; verify before applying.' : '';
const discountCard = discount ? '<div style="margin:20px 0;padding:14px 16px;background:#fff9db;border-left:4px solid #fece00"><strong>Discount request</strong><br>' + esc(discount) + '</div>' : '';
// Fixed Google Maps destinations built from address fields, never a URL supplied
// by the browser. Unit information stays visible but is omitted from the map
// search so it does not interfere with locating the street address.
const hasAddress = Boolean(lead.street_address && lead.city && lead.state && lead.postal_code);
const propertyAddress = hasAddress ? [lead.street_address, lead.address_line2, lead.city + ', ' + lead.state + ' ' + lead.postal_code].filter(Boolean).join(', ') : '';
const mapQuery = hasAddress ? encodeURIComponent([lead.street_address, lead.city, lead.state + ' ' + lead.postal_code, 'USA'].join(', ')) : '';
const mapUrl = 'https://www.google.com/maps/search/?api=1&query=' + mapQuery;
const directionsUrl = 'https://www.google.com/maps/dir/?api=1&destination=' + mapQuery + '&travelmode=driving';
const locationCard = '<h2 style="font-size:18px;margin:24px 0 10px">Property location</h2><table role="presentation" style="width:100%;border-collapse:separate;background:#ffffff;border:1px solid #fece00;border-radius:10px;margin-bottom:24px"><tr><td style="padding:18px">' + (hasAddress
  ? '<p style="font-size:19px;line-height:1.4;font-weight:bold;margin:0 0 16px">' + esc(propertyAddress) + '</p><a href="' + esc(mapUrl) + '" target="_blank" rel="noopener noreferrer" style="display:inline-block;background:#fece00;color:#000000;text-decoration:none;border-radius:7px;padding:12px 16px;font-size:14px;font-weight:bold;margin:0 8px 8px 0">View map</a><a href="' + esc(directionsUrl) + '" target="_blank" rel="noopener noreferrer" style="display:inline-block;background:#fff;color:#000000;text-decoration:none;border:1px solid #000000;border-radius:7px;padding:11px 15px;font-size:14px;font-weight:bold;margin:0 0 8px">Get directions</a><p style="font-size:12px;color:#444444;margin:4px 0 0">Opens Google Maps using the customer-provided address. Confirm the location with the customer before visiting.</p>'
  : '<p style="margin:0;color:#444444">A full property address was not provided by this older form. Confirm the street address with the customer before visiting.</p>') + '</td></tr></table>';
const action = '<div style="margin:24px 0"><a href="tel:' + phoneHref + '" style="display:inline-block;padding:14px 20px;margin:0 8px 8px 0;background:#fece00;color:#000000;text-decoration:none;border-radius:8px;font-weight:bold">Call customer</a><a href="sms:' + phoneHref + '" style="display:inline-block;padding:13px 19px;margin:0 0 8px;border:1px solid #000000;border-radius:8px;color:#000000;text-decoration:none;font-weight:bold">Text customer (mobile)</a><p style="margin:4px 0;font-size:17px;font-weight:bold">' + esc(phoneHref) + '</p><p style="font-size:12px;line-height:1.5;color:#444444;margin:4px 0 0">The text link opens a compatible messaging app; it does not send automatically. If your email app or desktop does not open it, copy the number above into your messaging app.</p></div>';
const html = '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="margin:0;background:#f4f4f4;color:#000000;font-family:Arial,sans-serif;line-height:1.5"><table role="presentation" style="width:100%;padding:24px 10px"><tr><td align="center"><table role="presentation" style="width:100%;max-width:640px;background:#ffffff;border:1px solid #dedede;border-radius:12px;overflow:hidden"><tr><td style="background:#000000;color:#ffffff;padding:24px 28px;border-top:6px solid #fece00"><div style="font-size:14px;font-weight:bold;letter-spacing:2px;color:#fece00">LC MARKETING</div><div style="font-size:24px;font-weight:bold;margin-top:6px">Paez Tree Service</div><div style="font-size:14px;color:#ffffff">Website lead notification</div></td></tr><tr><td style="padding:24px 28px"><div style="font-size:12px;text-transform:uppercase;color:#000000;font-weight:bold">' + esc(received) + '</div><h1 style="font-size:25px;line-height:1.25;margin:10px 0 16px">' + heading + '</h1><p style="font-size:18px;margin-bottom:4px"><strong>' + esc(lead.name) + '</strong> requested <strong>' + esc(lead.service) + '</strong>.</p><p style="color:#444444;margin-top:4px">Preferred contact: ' + esc(lead.contact_preference) + ' · Language: ' + esc(language) + '</p>' + action + discountCard + locationCard + '<h2 style="font-size:18px">Job &amp; contact details</h2>' + table([row('Service',lead.service),row(lead.service === 'Stump Removal' ? 'Stump count' : 'Tree / stump count',lead.tree_count),...(lead.tree_height ? [row('Approx. tree height',lead.tree_height)] : []),row('Discount code',lead.discount_code || 'None requested'),row('ZIP code',lead.postal_code),row('Timing',lead.timeline),row('Phone',lead.phone),row('Email',lead.email),row('Details',lead.details)]) + '<h2 style="font-size:18px">Where the inquiry came from</h2>' + table([row('Page',lead.page_url),row('Referrer',lead.referrer),row('Campaign source',lead.utm_source),row('Campaign medium',lead.utm_medium),row('Campaign',lead.utm_campaign),row('Ad content / keyword',[lead.utm_content,lead.utm_term].filter(Boolean).join(' / ')),row('Browser language',lead.browser_language),row('Visitor time zone',lead.timezone),row('Screen area',lead.viewport)]) + '<p style="font-size:13px;color:#555555">Saved in the <strong>paez-leads</strong> log. Reference: ' + esc(lead.lead_id) + '<br>Campaign and device details are supplied by the visitor’s browser; blank fields mean they were unavailable.</p></td></tr><tr><td style="padding:18px 28px;background:#f4f4f4;color:#444444;font-size:12px">Prepared by LC Marketing for Paez Tree Service.<br>Delivered to mrmushmushow@gmail.com. Paez notifications are disabled until enabled by LC Marketing.</td></tr></table></td></tr></table></body></html>';
return [{json:{lead_id:lead.lead_id, email:lead.email, html, subject:(emergency?'[URGENT] ':'')+'Paez Tree Service | '+lead.service+' | '+lead.name.replace(/[\r\n]/g,' ')}}];
